import json
import yaml

from quilldown_spec import PackagePart


def test_load_json_packagepart():
    json_data = r"""
    {
      "name": "sample",
      "contentType": "sample",
      "role": "sample"
    }
    """
    data = json.loads(json_data, strict=False)
    instance = PackagePart.load(data)
    assert instance is not None
    assert instance.name == "sample"
    assert instance.content_type == "sample"
    assert instance.role == "sample"


