def test_roundtrip_json_packagepart():
    """Test that load -> save -> load produces equivalent data."""
    json_data = r"""
    {
      "name": "sample",
      "contentType": "sample",
      "role": "sample"
    }
    """
    original_data = json.loads(json_data, strict=False)
    instance = PackagePart.load(original_data)
    saved_data = instance.save()
    reloaded = PackagePart.load(saved_data)
    assert reloaded is not None
    assert reloaded.name == "sample"
    assert reloaded.content_type == "sample"
    assert reloaded.role == "sample"


